// Host test for lib/management (bundle parsing / applying; the ECDSA check is
// replaced by a stand-in — verified with mbedTLS on the bench).
// Bundles generated by examples/hospital/bundle.py (dev management key).
// Run from firmware/test/host:
//   g++ -std=c++11 -Wall -Wextra -I../../lib/access_decision/src -I../../lib/management/src test_management.cpp ../../lib/management/src/management.cpp ../../lib/access_decision/src/*.cpp -o tm && ./tm

#include <cstdio>
#include <cstring>
#include <vector>

#include "management.h"

using namespace opencylinder;

static int failures = 0;
#define CHECK(cond)                                                        \
  do {                                                                     \
    if (!(cond)) {                                                         \
      std::printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond);          \
      ++failures;                                                          \
    }                                                                      \
  } while (0)

static const uint8_t kFull[] = {0x01, 0x00, 0x31, 0x43, 0x4F, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x64, 0x00, 0x00, 0x00, 0x10, 0x52, 0x05, 0x6B, 0x10, 0xF5, 0x07, 0x6B, 0x49, 0x00, 0x12, 0x08, 0x00, 0xD3, 0x07, 0x00, 0x00, 0xFF, 0xFF, 0xFF, 0xFF, 0x20, 0x1E, 0x00, 0x01, 0x7F, 0x68, 0x01, 0xB0, 0x04, 0x00, 0x00, 0x00, 0x00, 0x02, 0x3F, 0x2C, 0x01, 0x94, 0x02, 0x00, 0x00, 0x00, 0x00, 0x03, 0x1F, 0xA4, 0x01, 0x38, 0x04, 0x00, 0x00, 0x00, 0x00, 0x21, 0x1A, 0x00, 0x43, 0x45, 0x54, 0x2D, 0x31, 0x43, 0x45, 0x53, 0x54, 0x2C, 0x4D, 0x33, 0x2E, 0x35, 0x2E, 0x30, 0x2C, 0x4D, 0x31, 0x30, 0x2E, 0x35, 0x2E, 0x30, 0x2F, 0x33, 0x74, 0x5A, 0x39, 0x84, 0x27, 0xAA, 0x20, 0x5D, 0x8F, 0xE8, 0x88, 0x61, 0xC7, 0x75, 0xCA, 0xB7, 0x34, 0xB5, 0xD5, 0x79, 0xAA, 0x57, 0x48, 0xBA, 0x62, 0x0C, 0x45, 0xC1, 0x3B, 0x1F, 0x44, 0x2E, 0xE3, 0x34, 0x06, 0x64, 0x82, 0x2F, 0x91, 0x36, 0x30, 0x02, 0x12, 0x1E, 0x26, 0x52, 0xB4, 0x83, 0x12, 0xAB, 0xEA, 0x77, 0xAC, 0x26, 0x93, 0x6A, 0x02, 0x8F, 0x5A, 0x3D, 0x97, 0x8D, 0x10, 0x75};
static const uint8_t kAddRemove[] = {0x01, 0x00, 0x31, 0x43, 0x4F, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x65, 0x00, 0x00, 0x00, 0x4C, 0x52, 0x05, 0x6B, 0x10, 0xF5, 0x07, 0x6B, 0x12, 0x00, 0x10, 0x08, 0x00, 0xD1, 0x07, 0x00, 0x00, 0x20, 0x60, 0x05, 0x6B, 0x11, 0x04, 0x00, 0xD3, 0x07, 0x00, 0x00, 0x8C, 0x5F, 0xA2, 0xA3, 0x33, 0x9C, 0x24, 0x9E, 0xEA, 0xC5, 0x58, 0x40, 0xF3, 0x36, 0xAF, 0xDB, 0x44, 0x8F, 0x45, 0x9D, 0x66, 0x74, 0xF7, 0x9C, 0x7C, 0x59, 0x3C, 0x8C, 0x72, 0xB7, 0xE2, 0x85, 0x16, 0xB1, 0xE6, 0xC5, 0x04, 0xB6, 0x69, 0xEA, 0x44, 0xFA, 0x6A, 0x27, 0xD2, 0x4E, 0x15, 0x72, 0xB4, 0x19, 0xBC, 0x0F, 0x1A, 0x27, 0x27, 0xA1, 0x85, 0x26, 0x9B, 0x95, 0xDA, 0x49, 0x49, 0xE4};

static bool sigOk(const uint8_t*, size_t, const uint8_t[65]) { return true; }
static bool sigBad(const uint8_t*, size_t, const uint8_t[65]) { return false; }

int main() {
  const uint8_t site[3] = {0x31, 0x43, 0x4F};
  const uint8_t other[3] = {0x01, 0x02, 0x03};
  const uint8_t dev[8] = {0, 0, 1, 2, 3, 4, 5, 6};
  const uint8_t pub[65] = {0x04};
  const uint32_t t = 1795510800;
  ManagedState st;
  ApplySummary sum;

  // Full maintenance bundle: blacklist replace + 3 profiles + TZ
  CHECK(applyBundle(kFull, sizeof kFull, site, dev, pub, sigOk, false, 0, st, sum) == BundleStatus::Applied);
  CHECK(st.lastSequence == 100 && sum.issuedAt == t);
  CHECK(st.blacklist.size() == 1 && st.blacklist[0].credentialId == 2003);
  CHECK(st.profiles.size() == 3 && st.profiles[1].id == 2 && st.profiles[1].days == 0x3F &&
        st.profiles[1].iv[0].from == 300 && st.profiles[1].iv[0].to == 660);
  CHECK(st.tzRule == "CET-1CEST,M3.5.0,M10.5.0/3");
  CHECK(sum.blacklistReplaced && sum.profilesReplaced && sum.tzReplaced);

  // Replay of the same bundle: stale (state unchanged), time still reported
  ManagedState before = st;
  CHECK(applyBundle(kFull, sizeof kFull, site, dev, pub, sigOk, true, t, st, sum) == BundleStatus::StaleSequence);
  CHECK(sum.issuedAt == t && st.lastSequence == 100 && st.blacklist.size() == before.blacklist.size());

  // Add 2001 (until t+3600), remove 2003
  CHECK(applyBundle(kAddRemove, sizeof kAddRemove, site, dev, pub, sigOk, true, t, st, sum) == BundleStatus::Applied);
  CHECK(st.lastSequence == 101 && sum.blacklistAdded == 1 && sum.blacklistRemoved == 1);
  CHECK(st.blacklist.size() == 1 && st.blacklist[0].credentialId == 2001);
  CHECK(activeBlacklist(st, true, t).size() == 1);
  CHECK(activeBlacklist(st, true, t + 3601).empty());     // entry expired
  CHECK(activeBlacklist(st, false, 0).size() == 1);       // time unknown: keep (fail safe)

  // Rejections leave the state untouched
  ManagedState fresh;
  CHECK(applyBundle(kFull, sizeof kFull, site, dev, pub, sigBad, false, 0, fresh, sum) == BundleStatus::BadSignature);
  CHECK(fresh.lastSequence == 0 && fresh.blacklist.empty());
  CHECK(applyBundle(kFull, sizeof kFull, other, dev, pub, sigOk, false, 0, fresh, sum) == BundleStatus::WrongSite);
  CHECK(applyBundle(kFull, sizeof kFull, site, dev, pub, sigOk, true, t + 3 * 86400, fresh, sum) == BundleStatus::Expired);
  CHECK(applyBundle(kFull, sizeof kFull - 1, site, dev, pub, sigOk, false, 0, fresh, sum) == BundleStatus::Malformed);
  std::vector<uint8_t> targeted(kFull, kFull + sizeof kFull);
  targeted[5] = 0x99;  // target_device != 0 and != this lock
  CHECK(applyBundle(targeted.data(), targeted.size(), site, dev, pub, sigOk, false, 0, fresh, sum) == BundleStatus::WrongDevice);
  CHECK(fresh.lastSequence == 0 && fresh.profiles.empty());

  if (failures == 0) std::printf("management host tests: all passed\n");
  return failures == 0 ? 0 : 1;
}
